args.command:
node --input-type=module -e "
import { applyCoupon } from './src/coupons.js';
import { priceLines } from './src/pricing.js';
import { roundHalfUpCents } from './src/money.js';
// Single-line carts: per-line and whole-subtotal formulas coincide.
for (const [subtotal, rate] of [[12243,7],[1760,7],[100,7],[199,7],[1,7],[10,3],[33,7],[50,10]]) {
  const priced = priceLines([{id:'a', unitPriceCents: subtotal, qty: 1}]);
  const res = applyCoupon(priced, rate);
  const whole = roundHalfUpCents(priced.discountedSubtotal * rate / 100);
  console.log(subtotal, rate, 'applyCoupon=', res.couponDiscount, 'wholeFormula=', whole, 'match=', res.couponDiscount === whole);
}
"

node --input-type=module -e "
import { priceLines } from './src/pricing.js';
const CART = [
  { id: 'a', unitPriceCents: 250, qty: 3 },
  { id: 'b', unitPriceCents: 1200, qty: 10 },
  { id: 'c', unitPriceCents: 99, qty: 7 },
];
const priced = priceLines(CART);
console.log('lines:', JSON.stringify(priced.lines));
console.log('discountedSubtotal:', priced.discountedSubtotal);
const sumGrossMinusDiscount = priced.lines.reduce((s, l) => s + (l.lineGross - l.lineDiscount), 0);
const sumNet = priced.lines.reduce((s, l) => s + l.lineNet, 0);
const allNetsExact = priced.lines.every(l => l.lineNet === l.lineGross - l.lineDiscount);
console.log('sum(lineGross-lineDiscount):', sumGrossMinusDiscount);
console.log('sum(lineNet):', sumNet);
console.log('every lineNet === lineGross - lineDiscount (no rounding):', allNetsExact);
console.log('raw spec sum 750+10800+693 =', 750 + 10800 + 693);
console.log('invariant discountedSubtotal === sum(lineGross-lineDiscount):', priced.discountedSubtotal === sumGrossMinusDiscount);
console.log('coupon whole-subtotal round(12243*7/100):', Math.floor(12243 * 7 / 100 + 0.5));
"

node -e "
import('./src/money.js').then(m => {
  const roundHalfUpCents = m.roundHalfUpCents;
  const vals = [(12243*7)/100, (750*7)/100, (10800*7)/100, (693*7)/100, 857.01, 52.5, 910.88, 857.009999, 857.010001, 52.499999, 52.500001];
  for (const v of vals) {
    console.log(v.toPrecision(17), '->', roundHalfUpCents(v));
  }
  console.log('12243*7 =', 12243*7, '/100 =', (12243*7)/100);
  console.log('1760*7/100 =', (1760*7)/100);
}).catch(e => { console.error('ERR', e); process.exit(1); });
"
